        predict: { q: { tr: "Eşik 0,5'te model temerrüdlerin yüzde kaçını yakalar?", en: "At threshold 0.5, what share of defaults does the model catch?" }, options: { tr: ["Yaklaşık %4", "Yaklaşık %50", "Yaklaşık %90"], en: ["About 4%", "About 50%", "About 90%"] }, answer: 0, explain: { tr: "Temerrüt oranı %2 civarında: neredeyse hiçbir başvurunun olasılığı 0,5'i geçmez.", en: "The default rate is around 2%: almost no application's probability exceeds 0.5." } },
        code: { tr: WI.tr + `\nprint(f"Eğitimdeki temerrüt sayısı: {y_e.sum()}   test temerrüt oranı: %{100 * y_t.mean():.2f}")\nprint(f"“Herkes öder” doğruluğu: %{100 * (1 - y_t.mean()):.1f}")\nfor esik in [0.5, 0.05]:\n    yakalanan = ((p >= esik) & (y_t == 1)).sum() / y_t.sum()\n    print(f"eşik {esik}: yakalanan temerrüt %{100 * yakalanan:.1f}   reddedilen başvuru %{100 * (p >= esik).mean():.1f}")\nfrom sklearn.metrics import average_precision_score\nprint("AUC:", round(roc_auc_score(y_t, p), 3), "| ortalama kesinlik:", round(average_precision_score(y_t, p), 3), f"(test prevalansı %{100 * y_t.mean():.1f})")`, en: WI.en + `\nprint(f"Defaults in training: {y_e.sum()}   test default rate: {100 * y_t.mean():.2f}%")\nprint(f"“Everyone pays” accuracy: {100 * (1 - y_t.mean()):.1f}%")\nfor thr in [0.5, 0.05]:\n    caught = ((p >= thr) & (y_t == 1)).sum() / y_t.sum()\n    print(f"threshold {thr}: defaults caught {100 * caught:.1f}%   applications rejected {100 * (p >= thr).mean():.1f}%")\nfrom sklearn.metrics import average_precision_score\nprint("AUC:", round(roc_auc_score(y_t, p), 3), "| average precision:", round(average_precision_score(y_t, p), 3), f"(test prevalence {100 * y_t.mean():.1f}%)")` },
